for (i=mid; i>=left; i--) temp[i] = A[i];
for (j=1; j<=right-mid; j++) temp[right-j+1] = A[j+mid];
// Merge sublists back to A
for (i=left,j=right,k=left; k<=right; k++)
if (Comp::prior(temp[i], temp[j])) A[k] = temp[i++];
else A[k] = temp[j--];
}
